"""Generate test-only image data from the public, AI-labelled demo artwork."""

import base64
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
IMAGES = ROOT / "app-store/2026-11-12/images"
OUTPUT = ROOT / "tool/store_capture/generated_data.dart"


def main():
    manifest = json.loads(
        (IMAGES.parent / "sources/material-manifest.json").read_text()
    )
    if manifest.get("publicEmail") is None:
        raise ValueError("Missing demo material manifest")
    with OUTPUT.open("w") as output:
        output.write(
            "// Generated by tool/store_capture/generate_demo_data.py.\n"
            "// Integration-test only; never imported by the app.\n"
            "// AI-labelled synthetic demo artwork; see app-store/2026-11-12/sources.\n"
        )
        for name, filename in (
            ("storeCafe", "demo-cafe-ai.png"),
            ("storePortrait", "demo-portrait-ai.png"),
        ):
            data = base64.b64encode((IMAGES / filename).read_bytes()).decode()
            output.write(f"const {name} =\n")
            for start in range(0, len(data), 100):
                output.write(f"    '{data[start:start + 100]}'\n")
            output.write("    ;\n")


if __name__ == "__main__":
    main()
